const S = {};
for (const i of $('Load settings').all()) { if (i.json.key) { let v = String(i.json.value == null ? '' : i.json.value).trim(); if (/^(true|false)$/i.test(v)) v = v.toLowerCase(); S[String(i.json.key).trim()] = v; } }
if (S.paused === 'true') return [];
const now = $now.setZone('America/Toronto');
if (now.weekday > 5 || now.hour < 8 || now.hour >= 18) return [];
const trig = $('Run now').isExecuted ? 'manual' : 'schedule';
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i;
const supE = new Set(); const supD = new Set();
for (const i of $('Load suppression').all()) { const e = String(i.json.email || '').trim().toLowerCase(); const d = String(i.json.domain || '').trim().toLowerCase(); if (e) supE.add(e); if (d) supD.add(d); }
const toDT = v => { const d = new Date(v); return isNaN(d.getTime()) ? null : DateTime.fromJSDate(d).setZone('America/Toronto'); };
const biz = (dt, n) => { let d = dt; let k = 0; while (k < n) { d = d.plus({ days: 1 }); if (d.weekday <= 5) k++; } return d.set({ hour: 9, minute: 30, second: 0, millisecond: 0 }); };
const isTest = r => String(r.kind || '').toLowerCase() === 'test' || /^TEST\b/.test(String(r.business_name || ''));
const blocked = r => { const e = String(r.public_email || '').trim().toLowerCase(); return supE.has(e) || supD.has(e.split('@')[1] || '') || r.no_solicitation_notice === true; };
const leads = $('Load leads').all().map(i => i.json).filter(r => r && r.id);
const out = [];
// 1. Sync: drafts Stellan sent by hand from Gmail become SENT so follow-ups can be scheduled.
const sync = leads.filter(r => !isTest(r) && EMAIL_RE.test(String(r.public_email || '').trim()) && ((String(r.status) === 'NEEDS_REVIEW' && r.gmail_draft_id) || String(r.status) === 'APPROVED')).slice(0, 10);
for (const r of sync) {
  const created = toDT(r.createdAt) || now.minus({ days: 1 });
  out.push({ json: { kind: 'sync', lead_id: r.id, status: String(r.status), email: String(r.public_email).trim().toLowerCase(), after_epoch: Math.floor(created.toSeconds()), business_name: r.business_name || '', campaign_id: r.campaign_id || S.campaign_id || '', trigger: trig, f1_days: parseInt(S.followup_1_business_days || '4', 10) } });
}
// 2. Follow-ups that are due.
const max = parseInt(S.max_followups || '2', 10);
const batch = parseInt(S.followup_batch || '2', 10);
const f2 = parseInt(S.followup_2_business_days || '7', 10);
const due = leads.filter(r => {
  if (isTest(r) || String(r.status) !== 'SENT' || r.reply_class || blocked(r)) return false;
  if ((parseInt(r.followup_count || 0, 10)) >= max) return false;
  if (!r.gmail_thread_id || !r.gmail_message_id || !r.claim_token) return false;
  if (!EMAIL_RE.test(String(r.public_email || '').trim())) return false;
  const at = toDT(r.next_followup_at); return !!at && at <= now;
}).slice(0, batch);
const far = now.plus({ years: 50 }).toISO();
for (const r of due) {
  const count = parseInt(r.followup_count || 0, 10); const no = count + 1;
  let research = ''; try { research = typeof r.research_json === 'string' ? r.research_json : JSON.stringify(r.research_json || ''); } catch (e) { research = ''; }
  out.push({ json: { kind: 'followup', lead_id: r.id, email: String(r.public_email).trim().toLowerCase(), business_name: r.business_name || '', category: r.category || '', city: r.city || '', campaign_id: r.campaign_id || S.campaign_id || '', thread_id: r.gmail_thread_id, message_id: r.gmail_message_id, old_token: r.claim_token, new_token: 'fu-' + $execution.id + '-' + r.id + '-' + no, count: count, followup_no: no, max_followups: max, original_subject: r.email_subject || '', original_body: String(r.email_body || '').slice(0, 3000), research: research.slice(0, 2500), mode: (S.send_mode || 'DRAFT_ONLY').toUpperCase(), dry_run: S.dry_run === 'true', min_score: parseInt(S.min_quality_score || '80', 10), release_at: biz(now, 1).toISO(), next_after: no >= max ? far : biz(now, f2).toISO(), far: far, trigger: trig } });
}
return out;

const L = $('Loop leads').first().json;
const m = $json;
const ms = parseInt(m.internalDate || '0', 10);
const sent = ms ? DateTime.fromMillis(ms).setZone('America/Toronto') : $now.setZone('America/Toronto');
let d = sent; let k = 0; while (k < L.f1_days) { d = d.plus({ days: 1 }); if (d.weekday <= 5) k++; }
return [{ json: { gmail_id: m.id, thread_id: m.threadId || m.id, sent_at: sent.toISO(), next_followup_at: d.set({ hour: 9, minute: 30, second: 0, millisecond: 0 }).toISO() } }];

const items = $input.all().map(i => i.json);
const msgs = (items.length === 1 && Array.isArray(items[0].messages)) ? items[0].messages : items;
const L = $('Loop leads').first().json;
let hasReply = false; let header = '';
for (const m of msgs) {
  if (!m || !m.id) continue;
  const labels = (m.labels || []).map(l => String(l.id || l.name || '')).concat(m.labelIds || []);
  if (m.id === L.message_id) header = m['Message-ID'] || m['Message-Id'] || m['Message-id'] || '';
  if (!labels.includes('SENT') && !labels.includes('DRAFT')) hasReply = true;
}
return [{ json: { has_reply: hasReply, msg_id_header: String(header), message_count: msgs.length } }];

const L = $('Loop leads').first().json;
const clean = s => String(s == null ? '' : s).replace(/[{}]/g, '');
const P = [
  'Prospect business: ' + clean(L.business_name) + (L.category ? ' (' + clean(L.category) + ')' : '') + (L.city ? ', ' + clean(L.city) : ''),
  'This is follow-up number ' + L.followup_no + ' of at most ' + L.max_followups + (L.followup_no >= L.max_followups ? ' (the final one).' : '.'),
  '',
  'ORIGINAL EMAIL SUBJECT: ' + clean(L.original_subject),
  'ORIGINAL EMAIL BODY:', clean(L.original_body || '(not stored)'),
  '',
  'VERIFIED RESEARCH NOTES (the only facts about this business you may use):', clean(L.research || '(none)')
];
return [{ json: { prompt: P.join('\n') } }];

const L = $('Loop leads').first().json;
const FOOTER = ['', '', '--', 'Stellan Rowbotham, FlowPilot Automation', 'stellanrowbotham@gmail.com | https://flowpilot-rob9iwxx.manus.space', 'Business information: https://project28751.websitepublisher.ai/privacy.html', 'I found your business email on your website. If you would rather not hear from me, reply "stop" and I will not contact you again.'].join('\n');
const w = ($('AI write follow-up').first().json || {}).output;
const c = ($('AI critic').first().json || {}).output;
const subject = 'Re: ' + String(L.original_subject || 'my earlier email').replace(/^re:\s*/i, '');
if (!w || !w.body || String(w.body).trim().length < 20) {
  return [{ json: { route: 'ai_failed', reason: 'AI writer unavailable or empty' } }];
}
let body = String(w.body).trim();
let decision = 'HUMAN_REVIEW'; const reasons = []; let scores = {};
const SC = ['quality_score','personalization_score','relevance_score','credibility_score','clarity_score','cta_score'];
if (!c || typeof c.quality_score !== 'number') { reasons.push('critic unavailable'); }
else {
  for (const k of SC) scores[k] = c[k];
  const flags = (c.compliance_flags || []).filter(Boolean); const facts = (c.factual_issues || []).filter(Boolean);
  if (flags.length) reasons.push('compliance: ' + flags.join('; '));
  else if (c.decision === 'APPROVE' && c.quality_score >= L.min_score && !facts.length) decision = 'APPROVE';
  else if (c.decision === 'REWRITE' && c.revised_body) { body = String(c.revised_body).trim(); reasons.push('critic revised it (score ' + c.quality_score + '), please review'); }
  else reasons.push('critic ' + c.decision + ', score ' + c.quality_score + (facts.length ? ', facts: ' + facts.join('; ') : ''));
}
const words = body.split(/\s+/).filter(Boolean).length;
const checks = [];
if (words < 25 || words > 150) checks.push('length ' + words + ' words');
if (/https?:\/\//i.test(body)) checks.push('contains a link');
if (/\[[^\]]*\]/.test(body)) checks.push('placeholder brackets');
if (/guarantee|\b\d{1,3}\s?%|testimonial|case stud|clients? (like|such as)|limited time|act now|last chance|only \d+ spots/i.test(body)) checks.push('unsupported claim or pressure wording');
if (/unsubscribe|reply "stop"/i.test(body)) checks.push('duplicate opt-out text (footer adds it)');
if (checks.length) { decision = 'HUMAN_REVIEW'; reasons.push('checks: ' + checks.join(', ')); }
const route = L.dry_run ? 'dry' : (decision === 'APPROVE' && L.mode === 'SEND' ? 'send' : 'draft');
return [{ json: { route: route, decision: decision, reasons: reasons.join(' | ').slice(0, 900), subject: subject, final_body: body + FOOTER, scores: scores, words: words } }];

const L = $('Loop leads').first().json; const G = $('Gate').first().json; const T = $('Inspect thread').first().json;
try {
  const enc = s => '=?UTF-8?B?' + Buffer.from(s, 'utf8').toString('base64') + '?=';
  const h = ['To: ' + L.email, 'Subject: ' + enc(G.subject), 'MIME-Version: 1.0', 'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64'];
  if (T.msg_id_header) { h.push('In-Reply-To: ' + T.msg_id_header); h.push('References: ' + T.msg_id_header); }
  const bodyB64 = Buffer.from(G.final_body, 'utf8').toString('base64').replace(/(.{76})/g, '$1\r\n');
  const mime = h.join('\r\n') + '\r\n\r\n' + bodyB64;
  const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  return [{ json: { raw: raw, threadId: L.thread_id } }];
} catch (e) { return [{ json: { raw: '', threadId: L.thread_id, build_error: String(e && e.message || e) } }]; }
